/**
 * Install scripts that drop backgrounds into Microsoft Teams' custom
 * background folder. Teams has no API or deep link for adding a personal
 * background; the supported path is "Add new" in the meeting UI. These
 * scripts reproduce what that button does: copy `<guid>.jpg` and
 * `<guid>_thumb.jpg` into Teams' Uploads folder.
 *
 * Every value in the scripts is generated by the server (ids, GUIDs, the
 * configured origin). User-provided text such as titles never appears in
 * them, because they are meant to be piped straight into a shell.
 */
import { config } from './config.ts'
import { imageHref } from './images.ts'

export interface InstallItem {
  id: string
  teamsGuid: string
}

const GUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
const ID = /^[a-z0-9]{10}$/

function urlsFor(item: InstallItem) {
  if (!GUID.test(item.teamsGuid) || !ID.test(item.id)) {
    throw new Error(`Refusing to put unexpected id in an install script: ${item.id}`)
  }
  return {
    guid: item.teamsGuid,
    image: new URL(imageHref(item.id, 'full'), config.publicOrigin).href,
    thumb: new URL(imageHref(item.id, 'thumb'), config.publicOrigin).href,
  }
}

/** Run with: irm <url> | iex */
export function windowsScript(items: InstallItem[]): string {
  let entries = items
    .map(urlsFor)
    .map((u) => `  @{ Guid = '${u.guid}'; Image = '${u.image}'; Thumb = '${u.thumb}' }`)
    .join(',\n')

  return `# Adds ${items.length} background(s) from ${config.publicOrigin} to Microsoft Teams.
# Writes only to Teams' own custom-background folder for the current user.
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$backgrounds = @(
${entries}
)

$targets = @(
  # New Teams (2023+)
  @{ App = (Join-Path $env:LOCALAPPDATA 'Packages\\MSTeams_8wekyb3d8bbwe');
     Dir = (Join-Path $env:LOCALAPPDATA 'Packages\\MSTeams_8wekyb3d8bbwe\\LocalCache\\Microsoft\\MSTeams\\Backgrounds\\Uploads') },
  # Classic Teams
  @{ App = (Join-Path $env:APPDATA 'Microsoft\\Teams');
     Dir = (Join-Path $env:APPDATA 'Microsoft\\Teams\\Backgrounds\\Uploads') }
)

$installed = 0
foreach ($target in $targets) {
  if (-not (Test-Path $target.App)) { continue }
  New-Item -ItemType Directory -Force -Path $target.Dir | Out-Null
  foreach ($bg in $backgrounds) {
    Invoke-WebRequest -UseBasicParsing -Uri $bg.Image -OutFile (Join-Path $target.Dir "$($bg.Guid).jpg")
    Invoke-WebRequest -UseBasicParsing -Uri $bg.Thumb -OutFile (Join-Path $target.Dir "$($bg.Guid)_thumb.jpg")
  }
  Write-Host "Added $($backgrounds.Count) background(s) to $($target.Dir)"
  $installed++
}

if ($installed -eq 0) {
  Write-Warning "Couldn't find Microsoft Teams for this user. Download the image instead and use 'Add new' under Backgrounds in a meeting."
} else {
  Write-Host "Done. Open Teams > Settings > Devices > Video effects, or Backgrounds in a meeting. Restart Teams if they don't show up yet."
}
`
}

/** Run with: curl -fsSL <url> | sh */
export function macScript(items: InstallItem[]): string {
  let lines = items
    .map(urlsFor)
    .map(
      (u) =>
        `  curl -fsSL '${u.image}' -o "$dir/${u.guid}.jpg"\n` +
        `  curl -fsSL '${u.thumb}' -o "$dir/${u.guid}_thumb.jpg"`,
    )
    .join('\n')

  return `#!/bin/sh
# Adds ${items.length} background(s) from ${config.publicOrigin} to Microsoft Teams.
# Writes only to Teams' own custom-background folder for the current user.
set -eu

installed=0

install_into() {
  app="$1"
  dir="$2"
  [ -d "$app" ] || return 0
  mkdir -p "$dir"
${lines}
  echo "Added ${items.length} background(s) to $dir"
  installed=$((installed + 1))
}

# New Teams (2023+)
install_into "$HOME/Library/Containers/com.microsoft.teams2" \\
  "$HOME/Library/Containers/com.microsoft.teams2/Data/Library/Application Support/Microsoft/MSTeams/Backgrounds/Uploads"
# Classic Teams
install_into "$HOME/Library/Application Support/Microsoft/Teams" \\
  "$HOME/Library/Application Support/Microsoft/Teams/Backgrounds/Uploads"

if [ "$installed" -eq 0 ]; then
  echo "Couldn't find Microsoft Teams for this user. Download the image instead and use 'Add new' under Backgrounds in a meeting." >&2
  exit 1
fi
echo "Done. Open Teams > Settings > Devices > Video effects, or Backgrounds in a meeting. Restart Teams if they don't show up yet."
`
}

export function windowsCommand(scriptUrl: string) {
  return `irm ${scriptUrl} | iex`
}

export function macCommand(scriptUrl: string) {
  return `curl -fsSL ${scriptUrl} | sh`
}

export function scriptResponse(body: string, kind: 'windows' | 'mac') {
  return new Response(body, {
    headers: {
      'Content-Type': 'text/plain; charset=utf-8',
      'Cache-Control': 'no-store',
      'Content-Disposition': `inline; filename="add-to-teams.${kind === 'windows' ? 'ps1' : 'sh'}"`,
      'X-Content-Type-Options': 'nosniff',
    },
  })
}
